riceMin) ?>" aria-label="Minimum price" aria-valuetext="<?= $e(CatalogHtml::inr($priceMin)) ?>" data-pf="price-low"/><input class="ZxDzjq_handle" type="range" autocomplete="off" min="<?= $e($priceMin) ?>" max="<?= $e($priceMax) ?>" step="<?= $e($priceStep) ?>" value="<?= $e($priceMax) ?>" aria-label="Maximum price" aria-valuetext="<?= $e(CatalogHtml::inr($priceMax)) ?>" data-pf="price-high"/></div><button type="button" class="ZxDzjq_reset" disabled="" data-pf="price-reset">Reset price range</button><ul class="ZxDzjq_presets" aria-label="Quick price ranges"><?php foreach ($presets as [$low, $high]) { $from = $low ?? $priceMin; $to = $high ?? $priceMax; ?><li><button type="button"<?= ($from === $priceMin && $to === $priceMax) ? ' class="ZxDzjq_presetActive"' : '' ?> aria-pressed="<?= ($from === $priceMin && $to === $priceMax) ? 'true' : 'false' ?>" data-from="<?= $e($from) ?>" data-to="<?= $e($to) ?>" data-pf="price-preset"><?= $e($presetLabel($low, $high)) ?></button></li><?php } ?></ul></div></div><?php if ($fabricNames !== []) { ?><div class="_4HCqHa_filterGroup" role="group" aria-label="Fabric"><h3>Fabric</h3><?php foreach ($fabricNames as $i => $fabric) { ?><label class="_4HCqHa_choice"<?= ($i >= 5 && !$showAllFabrics) ? ' hidden=""' : '' ?> data-pf="fabric-choice"><input type="checkbox" autocomplete="off" value="<?= $e($fabric) ?>"<?= in_array($fabric, $selectedFabrics, true) ? ' checked=""' : '' ?> data-pf="fabric"/><?= $e($fabric) ?> (<?= $e($count('fabric', $fabric)) ?>)</label><?php } ?><?php if (count($fabricNames) > 5) { ?><button type="button" class="_4HCqHa_showMore" data-pf="fabric-more"><?= $showAllFabrics ? '− Show Less' : '+ Show More' ?></button><?php } ?></div><?php } ?><?php if ($colorNames !== []) { ?><div class="_4HCqHa_filterGroup" role="group" aria-label="Color"><h3>Color</h3><div class="_4HCqHa_colorChips"><?php foreach ($colorNames as $color) { ?><button type="button" class="_4HCqHa_colorChip" aria-pressed="false" data-value="<?= $e($color) ?>" data-pf="color"><?= $e($color) ?></button><?php } ?></div></div><?php } ?><div class="_4HCqHa_filterGroup" role="group" aria-label="Availability"><h3>Availability</h3><label class="_4HCqHa_choice"><input type="checkbox" autocomplete="off" data-pf="in-stock"/>In Stock (<?= $e($inStockCount) ?>)</label></div><button type="button" class="_4HCqHa_showMore" data-pf="clear"<?= $hasFilters ? '' : ' hidden=""' ?>>Clear all filters</button></div></aside><section class="_4HCqHa_listing" id="catalog-top" aria-label="New arrivals"><div class="_4HCqHa_intro"><div class="_4HCqHa_introTitle"><h1><?= $e($heading ?? "New Arrivals") ?></h1><p>Discover the latest additions to our exclusive collection</p></div><div class="_4HCqHa_promise"><img alt="" loading="lazy" width="53" height="47" decoding="async" data-nimg="1" style="color:transparent" src="/assets/images/figma/lotus-emblem.svg"/><div><p class="_4HCqHa_promiseTagline">Fresh Styles. Timeless Grace.</p><p class="_4HCqHa_promiseCopy">Handpicked designs for the modern you.</p></div></div></div><div class="_4HCqHa_toolbar"><p data-pf="count"><?= $e($matchCount) ?> <?= $matchCount === 1 ? 'Product' : 'Products' ?></p><label class="_4HCqHa_sort"><span>Sort by:</span><span class="_4HCqHa_sortField"><select data-pf="sort" autocomplete="off"><option value="featured" selected="">Featured</option><option value="price-asc">Price: Low to High</option><option value="price-desc">Price: High to Low</option></select><img class="_4HCqHa_sortArrow" alt="" loading="lazy" width="27" height="27" decoding="async" data-nimg="1" style="color:transparent" src="/assets/images/figma/sort-arrow.svg"/></span></label></div><?php
$listing = true;
$gridClass = '_4HCqHa_grid';
$catalogError = false;
require dirname(__DIR__) . '/partials/products.php';
?><div class="_4HCqHa_empty" data-pf="empty"<?= $matchCount > 0 ? ' hidden=""' : '' ?>><p>No products match these filters.</p><button type="button" data-pf="clear">Clear all filters</button></div><nav class="_4HCqHa_pagination" aria-label="Pagination" data-pf="pagination"<?= $totalPages > 1 ? '' : ' hidden=""' ?>><button type="button" class="_4HCqHa_pageArrow" disabled="" aria-label="Previous page">‹</button><?php foreach (CatalogHtml::pageList(1, $totalPages) as $entry) { ?><?php if ($entry === 'gap') { ?><span class="_4HCqHa_pageGap">…</span><?php } else { ?><button type="button"<?= $entry === 1 ? ' aria-current="page"' : '' ?> data-page="<?= $e($entry) ?>"><?= $e($entry) ?></button><?php } ?><?php } ?><button type="button" class="_4HCqHa_pageArrow"<?= $totalPages === 1 ? ' disabled=""' : '' ?> aria-label="Next page">›</button></nav></section></div></div><?php require dirname(__DIR__) . '/partials/footer.php'; ?></main>
